const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function normalizeString(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-L",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        scheduling: null,
        calendar_event_handoff: null,
        message_handoff: null,
        manual_review_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-L will not prepare scheduling when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "prepare_scheduling") {
  return fail({
    code: "SCHEDULING_NOT_REQUESTED",
    message: "source.next_action is not prepare_scheduling.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.provider) {
  return fail({
    code: "MISSING_PROVIDER",
    message: "config.provider is required."
  });
}

if (!config.mode) {
  return fail({
    code: "MISSING_MODE",
    message: "config.mode is required."
  });
}

if (!config.meeting_type) {
  return fail({
    code: "MISSING_MEETING_TYPE",
    message: "config.meeting_type is required."
  });
}

if (!config.meeting_title) {
  return fail({
    code: "MISSING_MEETING_TITLE",
    message: "config.meeting_title is required."
  });
}

const provider = normalizeString(config.provider).toLowerCase();
const mode = normalizeString(config.mode).toLowerCase();
const payload = source.payload || {};
const attendeeName = normalizeString(payload.name);
const attendeeEmail = normalizeString(payload.email);
const company = normalizeString(payload.company);

const supportedProviders = ["calendly", "cal_com", "google_calendar", "manual"];
const supportedModes = ["booking_link", "event_handoff", "manual_scheduling"];

if (!supportedProviders.includes(provider)) {
  return fail({
    code: "UNSUPPORTED_PROVIDER",
    message: "config.provider is not supported in C2-L v1.",
    details: [{ provider, supported_providers: supportedProviders }]
  });
}

if (!supportedModes.includes(mode)) {
  return fail({
    code: "UNSUPPORTED_MODE",
    message: "config.mode is not supported in C2-L v1.",
    details: [{ mode, supported_modes: supportedModes }]
  });
}

if (["calendly", "cal_com"].includes(provider) && mode !== "booking_link") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "Calendly and Cal.com v1 support booking_link mode only.",
    details: [{ provider, mode }]
  });
}

if (provider === "google_calendar" && mode !== "event_handoff") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "Google Calendar v1 supports event_handoff mode only.",
    details: [{ provider, mode }]
  });
}

if (provider === "manual" && mode !== "manual_scheduling") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "Manual provider supports manual_scheduling mode only.",
    details: [{ provider, mode }]
  });
}

if (mode === "booking_link" && !config.booking_url) {
  return fail({
    code: "MISSING_BOOKING_URL",
    message: "config.booking_url is required for booking_link mode."
  });
}

if (mode === "event_handoff") {
  if (!config.event_time || !config.event_time.start_time || !config.event_time.end_time) {
    return fail({
      code: "MISSING_EVENT_TIME",
      message: "config.event_time.start_time and config.event_time.end_time are required for event_handoff mode."
    });
  }

  if (!attendeeEmail) {
    return fail({
      code: "MISSING_ATTENDEE_EMAIL",
      message: "input.payload.email is required for event_handoff mode."
    });
  }
}

const scheduling = {
  provider,
  mode,
  status: "ready",
  meeting_type: config.meeting_type,
  meeting_title: config.meeting_title,
  duration_minutes: Number(config.duration_minutes || 30),
  timezone: config.timezone || "UTC",
  booking_url: config.booking_url || null,
  attendee: {
    name: attendeeName || null,
    email: attendeeEmail || null,
    company: company || null
  },
  scheduling_goal: config.scheduling_goal || null,
  manual_review_required: provider === "manual",
  prepared_at: nowIso()
};

let calendarEventHandoff = null;
let messageHandoff = null;
let manualReviewHandoff = null;
let nextAction = config.default_next_action || "scheduling_ready";

if (mode === "event_handoff") {
  const calendarConfig = config.calendar || {};

  calendarEventHandoff = {
    next_component: "google_calendar_adapter",
    input: {
      success: true,
      component_id: "C2-L",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "calendar_event_request",
      provider,
      action: "create_event",
      event: {
        title: config.meeting_title,
        start_time: config.event_time.start_time,
        end_time: config.event_time.end_time,
        timezone: config.timezone || "UTC",
        attendees: [
          {
            name: attendeeName || null,
            email: attendeeEmail
          }
        ],
        description: [
          config.scheduling_goal || "",
          company ? `Company: ${company}` : "",
          payload.message ? `Context: ${payload.message}` : ""
        ].filter(Boolean).join("\n"),
        calendar_id: calendarConfig.calendar_id || "primary",
        add_google_meet: calendarConfig.add_google_meet === true,
        reminders: calendarConfig.reminders || { use_default: true }
      },
      source_result: source,
      error: null,
      next_action: "create_calendar_event"
    },
    config: {
      provider: "google_calendar",
      adapter_required: true,
      default_next_action: "notify_attendees"
    }
  };

  nextAction = config.default_next_action || "create_calendar_event";
}

if (mode === "booking_link" && config.message_policy?.create_message_handoff === true) {
  const providerLabel = provider === "cal_com" ? "Cal.com" : "Calendly";

  messageHandoff = {
    next_component: "C4-E",
    input: {
      success: true,
      component_id: "C2-L",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "scheduling_message_request",
      payload: {
        name: attendeeName,
        email: attendeeEmail,
        company,
        message: payload.message || "",
        scheduling: {
          provider,
          provider_label: providerLabel,
          booking_url: config.booking_url,
          meeting_type: config.meeting_type,
          meeting_title: config.meeting_title,
          duration_minutes: Number(config.duration_minutes || 30),
          timezone: config.timezone || "UTC"
        }
      },
      scheduling,
      source_result: source,
      error: null,
      next_action: "generate_email_draft"
    },
    config: {
      email_type: config.message_policy.message_type || "scheduling_email",
      email_goal: `Invite recipient to schedule ${config.meeting_title} using ${providerLabel} booking link.`,
      recipient_context: "Scheduling invite for qualified/approved workflow contact.",
      client_ai_profile: config.client_ai_profile || {
        client_profile: {
          client_name: "Default Client"
        },
        audience_profile: {},
        voice_profile: {},
        offer_profile: {},
        email_rules: {
          preferred_length: "short",
          cta_style: "clear booking link CTA"
        },
        risk_boundaries: {},
        approval_rules: {
          default_policy: "approval_required_before_external_action"
        }
      },
      llm: config.llm || {
        provider: "groq",
        endpoint: "https://api.groq.com/openai/v1/chat/completions",
        model: "llama-3.3-70b-versatile",
        temperature: 0.2,
        max_tokens: 700
      },
      default_next_action: "package_draft_for_approval"
    }
  };

  nextAction = config.default_next_action || "send_scheduling_message_for_approval";
}

if (mode === "manual_scheduling") {
  manualReviewHandoff = {
    next_component: "C5-E",
    input: {
      success: true,
      component_id: "C2-L",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "manual_scheduling_request",
      scheduling,
      source_result: source,
      error: null,
      next_action: "manual_review"
    },
    config: {
      queue_type: "manual_scheduling",
      review_reason: "Manual scheduling required because no booking provider/event handoff is configured.",
      reviewer_email: config.reviewer_email || "shwetabh.singh@lexnovahq.com",
      owner: "ops",
      priority: source.lead_qualification?.priority || "normal",
      allowed_actions: ["send_booking_link", "propose_times", "create_event", "request_more_info"],
      default_next_action: "notify_reviewer"
    }
  };

  nextAction = "manual_review";
}

return [
  {
    json: {
      success: true,
      component_id: "C2-L",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      scheduling,
      calendar_event_handoff: calendarEventHandoff,
      message_handoff: messageHandoff,
      manual_review_handoff: manualReviewHandoff,
      source_result: source,
      error: null,
      next_action: nextAction
    }
  }
];
